"""JupyterLab integration diagnostic checks."""

import shutil
import subprocess

from .models import CheckResult, CheckStatus


def run_checks(verbose: bool = False) -> list[CheckResult]:
    """Run JupyterLab integration diagnostic checks."""
    results = []
    results.append(_check_jupyter_installed())
    results.append(_check_server_extension())
    results.append(_check_lab_extension())
    results.append(_check_running_in_lab())

    # Cloud-specific checks
    try:
        from qbraid_core.client import QbraidClientV1

        if QbraidClientV1.running_in_lab():
            results.extend(_cloud_checks(verbose))
    except Exception:
        pass

    return results


def _check_jupyter_installed() -> CheckResult:
    """Check if JupyterLab is installed."""
    try:
        import jupyterlab

        version = jupyterlab.__version__
        return CheckResult(
            name="jupyterlab.installed",
            category="jupyterlab",
            status=CheckStatus.PASS,
            message=f"JupyterLab {version} is installed.",
        )
    except ImportError:
        return CheckResult(
            name="jupyterlab.installed",
            category="jupyterlab",
            status=CheckStatus.SKIP,
            message="JupyterLab is not installed (not required for CLI-only usage).",
        )


def _check_server_extension() -> CheckResult:
    """Check if jupyter_environment_manager server extension is installed."""
    try:
        import jupyter_environment_manager

        version = getattr(jupyter_environment_manager, "__version__", "unknown")
        return CheckResult(
            name="jupyterlab.server_extension",
            category="jupyterlab",
            status=CheckStatus.PASS,
            message=f"jupyter_environment_manager {version} is installed.",
        )
    except ImportError:
        return CheckResult(
            name="jupyterlab.server_extension",
            category="jupyterlab",
            status=CheckStatus.SKIP,
            message=(
                "jupyter_environment_manager not installed"
                " (required for JupyterLab integration)."
            ),
        )


def _check_lab_extension() -> CheckResult:
    """Check if lab extensions are properly built."""
    jupyter_bin = shutil.which("jupyter")
    if not jupyter_bin:
        return CheckResult(
            name="jupyterlab.lab_extension_built",
            category="jupyterlab",
            status=CheckStatus.SKIP,
            message="jupyter command not found.",
        )

    try:
        result = subprocess.run(
            [jupyter_bin, "labextension", "list"],
            capture_output=True,
            text=True,
            timeout=30,
            check=False,
        )
        output = result.stdout + result.stderr

        # Look for our extension in the output
        if "jupyter_environment_manager" in output or "qbraid" in output.lower():
            return CheckResult(
                name="jupyterlab.lab_extension_built",
                category="jupyterlab",
                status=CheckStatus.PASS,
                message="qBraid lab extension found in extension list.",
                details={"output": output[:500]} if output else None,
            )
        return CheckResult(
            name="jupyterlab.lab_extension_built",
            category="jupyterlab",
            status=CheckStatus.WARN,
            message="qBraid lab extension not found in 'jupyter labextension list'.",
            fix_hint="Rebuild extensions: jupyter lab build",
        )
    except subprocess.TimeoutExpired:
        return CheckResult(
            name="jupyterlab.lab_extension_built",
            category="jupyterlab",
            status=CheckStatus.ERROR,
            message="'jupyter labextension list' timed out.",
        )
    except Exception as exc:
        return CheckResult(
            name="jupyterlab.lab_extension_built",
            category="jupyterlab",
            status=CheckStatus.ERROR,
            message=f"Could not check lab extensions: {exc}",
        )


def _check_running_in_lab() -> CheckResult:
    """Check if we're running in qBraid Lab (cloud)."""
    try:
        from qbraid_core.client import QbraidClientV1

        in_lab = QbraidClientV1.running_in_lab()
        if in_lab:
            return CheckResult(
                name="jupyterlab.running_in_lab",
                category="jupyterlab",
                status=CheckStatus.PASS,
                message="Running in qBraid Lab (cloud=true in qbraidrc).",
            )
        return CheckResult(
            name="jupyterlab.running_in_lab",
            category="jupyterlab",
            status=CheckStatus.PASS,
            message="Not running in qBraid Lab (local environment).",
        )
    except Exception as exc:
        return CheckResult(
            name="jupyterlab.running_in_lab",
            category="jupyterlab",
            status=CheckStatus.ERROR,
            message=f"Could not determine lab status: {exc}",
        )


def _cloud_checks(verbose: bool = False) -> list[CheckResult]:  # noqa: ARG001
    """Additional checks when running on qBraid Lab (cloud)."""
    results = []

    # Check for user site-packages overriding system packages (known PD issue)
    results.append(_check_package_override())

    # Check server extension is enabled
    results.append(_check_server_extension_enabled())

    return results


def _check_package_override() -> CheckResult:
    """Check if user site-packages override system packages (PD issue)."""
    import site
    from pathlib import Path

    user_site = site.getusersitepackages()

    # Check if any qbraid packages exist in user site-packages
    user_site_path = Path(user_site)

    if not user_site_path.exists():
        return CheckResult(
            name="jupyterlab.package_override",
            category="jupyterlab",
            status=CheckStatus.PASS,
            message="No user site-packages directory.",
        )

    qbraid_in_user = list(user_site_path.glob("qbraid*"))
    if qbraid_in_user:
        names = [p.name for p in qbraid_in_user]
        return CheckResult(
            name="jupyterlab.package_override",
            category="jupyterlab",
            status=CheckStatus.WARN,
            message=(
                f"qBraid packages found in user site-packages: {names}."
                " These may override system packages."
            ),
            fix_hint=f"Remove stale packages: rm -rf {user_site}/qbraid_*",
            details={"user_site": str(user_site), "packages": names},
        )

    return CheckResult(
        name="jupyterlab.package_override",
        category="jupyterlab",
        status=CheckStatus.PASS,
        message="No qBraid packages in user site-packages (no override risk).",
    )


def _check_server_extension_enabled() -> CheckResult:
    """Check if the server extension is enabled in Jupyter config."""
    jupyter_bin = shutil.which("jupyter")
    if not jupyter_bin:
        return CheckResult(
            name="jupyterlab.server_extension_enabled",
            category="jupyterlab",
            status=CheckStatus.SKIP,
            message="jupyter command not found.",
        )

    try:
        result = subprocess.run(
            [jupyter_bin, "server", "extension", "list"],
            capture_output=True,
            text=True,
            timeout=30,
            check=False,
        )
        output = result.stdout + result.stderr

        if "jupyter_environment_manager" in output:
            if "enabled" in output.lower():
                return CheckResult(
                    name="jupyterlab.server_extension_enabled",
                    category="jupyterlab",
                    status=CheckStatus.PASS,
                    message="jupyter_environment_manager server extension is enabled.",
                )
            return CheckResult(
                name="jupyterlab.server_extension_enabled",
                category="jupyterlab",
                status=CheckStatus.FAIL,
                message="jupyter_environment_manager is installed but not enabled.",
                fix_hint="Enable it: jupyter server extension enable jupyter_environment_manager",
            )
        return CheckResult(
            name="jupyterlab.server_extension_enabled",
            category="jupyterlab",
            status=CheckStatus.WARN,
            message="jupyter_environment_manager not found in server extension list.",
        )
    except Exception as exc:
        return CheckResult(
            name="jupyterlab.server_extension_enabled",
            category="jupyterlab",
            status=CheckStatus.ERROR,
            message=f"Could not check server extensions: {exc}",
        )
